var n=`0973-sundubu-jjigae`;var t=`world-0973`;var s=`KR`;var a=`east-asia`;var o=4;var g=32;var r={en:`Sundubu Jjigae`,ua:`Сундубу ччіге`};var u={en:`Sundubu Jjigae is a South Korea dish made with garlic, yellow onion, shrimp, clam. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сундубу ччіге, страва кухні країни Південна Корея. Основні складники: часник, жовта цибуля, креветка, венерка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`yellow-onion`,130,`g`],[`gochugaru`,12,`g`],[`sesame-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[[`shrimp`,240,`g`],[`clam`,260,`g`],[`dashi-stock`,900,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 7 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 7 хвилин до готовності й м’якості.`,t:[`poaching`],m:7,i:[[`tofu-silken`,540,`g`],[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,65,`g`]]}];var h={slug:n,id:t,country:`KR`,region:a,servings:4,minutes:32,title:r,text:u,steps:d};export{s as country,h as default,t as id,g as minutes,a as region,o as servings,n as slug,d as steps,u as text,r as title};